function bool ApplyVersusFreeLookKey(EInputKey Key, EInputAction Action)
{
    local HPVersusHarry H;

    if (Key != IK_Alt && Key != IK_LAlt)
        return False;
    if (Action != IST_Press && Action != IST_Release)
        return True;

    H = GetLocalVersusPawn();
    if (H == None)
        return False;

    if (Action == IST_Press)
        H.bVersusFreeLook = 1;
    else
        H.bVersusFreeLook = 0;

    return True;
}

